import { useEffect, useState } from 'react'
import { useParams } from 'react-router-dom'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { toast } from 'sonner'
import { projectsService } from '@/integrations/supabase/projects'

export function ProjectSettingsPage() {
  const { projectId } = useParams()
  const qc = useQueryClient()
  const [title, setTitle] = useState('')
  const [description, setDescription] = useState('')

  const { data: project } = useQuery({
    queryKey: ['project', projectId],
    queryFn: () => projectsService.getProject(projectId ?? ''),
    enabled: !!projectId,
  })

  useEffect(() => {
    setTitle(project?.title ?? '')
    setDescription(project?.description ?? '')
  }, [project])

  const saveMut = useMutation({
    mutationFn: () => projectsService.updateProject(projectId ?? '', { title, description }),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['project', projectId] })
      toast.success('Project updated')
    },
    onError: (e: Error) => toast.error(e.message),
  })

  return (
    <div className="h-full overflow-y-auto p-6">
      <div className="max-w-2xl mx-auto">
        <h2 className="font-semibold mb-6">Project settings</h2>
        <div className="bg-surface rounded-xl border border-border p-6 flex flex-col gap-4">
          <div>
            <label className="text-sm font-medium block mb-1.5">Project title</label>
            <input value={title} onChange={(e) => setTitle(e.target.value)} className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent" />
          </div>
          <div>
            <label className="text-sm font-medium block mb-1.5">Description</label>
            <textarea value={description} onChange={(e) => setDescription(e.target.value)} rows={3} className="w-full rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent resize-none" />
          </div>
          <button onClick={() => saveMut.mutate()} disabled={saveMut.isPending} className="self-start bg-accent text-accent-foreground px-4 py-2 rounded-lg text-sm hover:opacity-90 disabled:opacity-50">
            {saveMut.isPending ? 'Saving…' : 'Save changes'}
          </button>
        </div>
      </div>
    </div>
  )
}
